<?php
session_start();if(empty($_SESSION['admin_ok'])){header('Location: admin.php');exit;}function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$file=__DIR__.'/data/orcamentos.json';$all=is_file($file)?json_decode((string)file_get_contents($file),true):[];if(!is_array($all))$all=[];$user=(string)($_SESSION['admin_user']??'');
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='delete'){$id=(string)($_POST['id']??'');foreach($all as &$q)if(($q['id']??'')===$id&&strcasecmp((string)($q['user']??''),$user)===0){if(in_array(($q['status']??'rascunho'),['enviado','aprovado'],true)){$q['status']='cancelado';$q['updated_at']=date('c');$q['history'][]=['at'=>date('c'),'user'=>$user,'event'=>'cancelled'];}else{$q['_delete']=true;}}unset($q);$all=array_values(array_filter($all,fn($q)=>empty($q['_delete'])));file_put_contents($file,json_encode($all,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);header('Location: orcamentos.php');exit;}
$quotes=array_values(array_filter($all,fn($q)=>strcasecmp((string)($q['user']??''),$user)===0));$st=trim($_GET['status']??'');$search=mb_strtolower(trim($_GET['busca']??''),'UTF-8');if($st!=='')$quotes=array_values(array_filter($quotes,fn($q)=>($q['status']??'rascunho')===$st));if($search!=='')$quotes=array_values(array_filter($quotes,fn($q)=>str_contains(mb_strtolower(($q['number']??'').' '.($q['customer']['name']??'').' '.($q['customer']['vehicle']??'').' '.($q['customer']['phone']??''),'UTF-8'),$search)));usort($quotes,fn($a,$b)=>strcmp($b['updated_at']??'',$a['updated_at']??''));
function qt($q){$t=0;foreach(($q['items']??[])as$i)if(is_numeric($i['price']??null))$t+=(float)$i['price']*(int)($i['qty']??1);return $t*(1-max(0,min(100,(float)($q['discount']??0)))/100);}$labels=['rascunho'=>'Rascunho','enviado'=>'Enviado','negociacao'=>'Em negociação','aprovado'=>'Aprovado','perdido'=>'Perdido','cancelado'=>'Cancelado'];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meus Orçamentos — HE</title><link rel="stylesheet" href="assets/css/style.css?v=20261002-layoutfix1"></head><body class="admin-page"><header class="admin-header"><div class="container admin-header-inner"><a href="index.php" class="logo logo-image"><img src="assets/eleds-logo.png" alt="HE"></a><div class="admin-actions"><a href="dashboard.php">Meu painel</a><a href="index.php">Catálogo</a><a href="admin.php?logout=1">Sair</a></div></div></header><main class="container admin-main"><div class="admin-title"><div><span class="section-kicker">COMERCIAL</span><h1>Meus orçamentos</h1><p><?=count($quotes)?> resultado(s)</p></div><a class="admin-primary" href="index.php">+ Novo orçamento</a></div>
<section class="admin-panel"><form method="get" class="crm-filter"><input name="busca" value="<?=e($_GET['busca']??'')?>" placeholder="Número, cliente, veículo ou telefone"><select name="status"><option value="">Todos os status</option><?php foreach($labels as$k=>$v):?><option value="<?=e($k)?>" <?=$st===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select><button class="admin-primary">Filtrar</button><a href="orcamentos.php">Limpar</a></form><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Número / cliente</th><th>Status</th><th>Itens</th><th>Total</th><th>Retorno</th><th>Ações</th></tr></thead><tbody><?php if(!$quotes):?><tr><td colspan="6">Nenhum orçamento encontrado.</td></tr><?php endif;?><?php foreach($quotes as$q):$units=0;foreach(($q['items']??[])as$i)$units+=(int)($i['qty']??1);?><tr><td><strong><?=e($q['number']??$q['id'])?></strong><br><?=e($q['customer']['name']??($q['note']??'Sem identificação'))?><br><small><?=e($q['customer']['vehicle']??'')?> <?=e($q['customer']['plate']??'')?></small></td><td><span class="crm-status s-<?=e($q['status']??'rascunho')?>"><?=e($labels[$q['status']??'rascunho']??'Rascunho')?></span></td><td><?=count($q['items']??[])?> produto(s) · <?=$units?> un.</td><td>R$ <?=number_format(qt($q),2,',','.')?></td><td><?=!empty($q['commercial']['return_date'])?e(date('d/m/Y',strtotime($q['commercial']['return_date']))):'—'?></td><td class="admin-row-actions"><a href="index.php?orcamento=<?=urlencode($q['id'])?>">Continuar</a><form method="post" onsubmit="return confirm('Confirmar esta ação?');"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($q['id'])?>"><button type="submit"><?=in_array(($q['status']??''),['enviado','aprovado'],true)?'Cancelar':'Excluir'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
